    </span>
  </div>
</template>

<script setup lang="ts">
import { computed } from 'vue';

const props = defineProps<{
  brand?: string;
}>();

const hasIcon = computed(() => {
  return [
    'visa',
    'mastercard',
    'american_express',
    'discover',
    'diners_club',
    'jcb',
    'union_pay',
    'cartes_bancaires',
  ].includes(props.brand || '');
});

const brandFriendlyName = computed(() => {
  switch (props.brand) {
    case 'visa':
      return 'Visa';
    case 'mastercard':
      return 'Mastercard';
    case 'american_express':
      return 'American Express';
    case 'discover':
      return 'Discover';
    case 'diners_club':
      return 'Diners Club';
    case 'jcb':
      return 'JCB';
    case 'union_pay':
      return 'Union Pay';
    case 'cartes_bancaires':
      return 'Cartes Bancaires';
    case 'eftpos_australia':
      return 'Eftpos Australia';
    default:
      return props.brand || 'Unknown card type';
  }
});
</script>
